#!/usr/bin/env python3
"""Offline checks for place.py with a fake docker. Run: python3 -I place_selftest.py"""
import json, os, re, shutil, stat, subprocess, sys, tempfile
import atexit as _a, shutil as _s
tmp = tempfile.mkdtemp(prefix="selftest-"); _a.register(_s.rmtree, tmp, True)
HERE = os.path.dirname(os.path.abspath(__file__))
fake = os.path.join(tmp, "docker"); log = os.path.join(tmp, "calls.txt")
# FAKE_STATEFILE: NAMEdoc's state lives in that file (stop -> exited, start/unpause -> running, a paused one cannot be stopped); otherwise FAKE_RUNNING says running
open(fake, "w").write('#!/bin/sh\necho "$@" >> ' + log + '\n[ "$1" = "create" ] && [ -n "$FAKE_FAIL" ] && { echo boom >&2; exit 1; }\n[ "$1" = "network" ] && [ "$2" = "inspect" ] && [ -z "$FAKE_NET" ] && exit 1\n'
                      'if [ -n "$FAKE_STATEFILE" ]; then case "$1" in\n'
                      '  stop) [ "$(cat "$FAKE_STATEFILE")" = paused ] && { echo "cannot stop a paused container" >&2; exit 1; }; echo exited > "$FAKE_STATEFILE"; exit 0;;\n'
                      '  start|unpause) echo running > "$FAKE_STATEFILE"; exit 0;;\n'
                      '  inspect) case "$*" in *place-*) echo exited;; *) cat "$FAKE_STATEFILE";; esac; exit 0;;\n'
                      'esac; fi\n'
                      '[ "$1" = "inspect" ] && { [ -n "$FAKE_RUNNING" ] && echo running || echo exited; }\n[ "$1" = "exec" ] && [ "$3" = "pgrep" ] && { [ -n "$FAKE_GAME" ] && { echo "42 S:\\\\game\\\\CoDWaW.exe"; exit 0; } || exit 1; }\n[ "$1" = "exec" ] && { case "$*" in *" -d "*) echo \'{"status":true}\';; *) echo \'{"pairings":[{"address":"10.0.0.5","id":"0123456789abcdef0123456789abcdef","name":"phone"}]}\';; esac; }\nexit 0\n')
os.chmod(fake, 0o755)
root = os.path.join(tmp, "places"); os.makedirs(root)
# a fake btrfs on PATH: a folder with a .fake-subvol file is a subvolume; a snapshot is a copy (read-only ones get .fake-ro); delete removes it
fakebin = os.path.join(tmp, "fakebin"); os.makedirs(fakebin); blog = os.path.join(tmp, "btrfs.txt")
open(os.path.join(fakebin, "btrfs"), "w").write(r'''#!/bin/sh
echo "$@" >> ''' + blog + r'''
[ "$1" = subvolume ] || exit 1
case "$2" in
  show) [ -f "$3/.fake-subvol" ] && { echo "Name: x"; exit 0; }; echo "ERROR: Not a Btrfs subvolume" >&2; exit 1;;
  snapshot) if [ "$3" = -r ]; then s=$4; t=$5; else s=$3; t=$4; [ -n "$FAKE_BTRFS_FAIL_RW" ] && { echo "no space left" >&2; exit 1; }
      [ -n "$FAKE_LOCK" ] && [ -e "$FAKE_LOCK" ] && echo "lock-held" >> ''' + blog + r'''; fi
    [ -f "$s/.fake-subvol" ] || { echo "ERROR: Not a Btrfs subvolume" >&2; exit 1; }
    [ -e "$t" ] && { echo "ERROR: exists" >&2; exit 1; }
    cp -a "$s" "$t" || exit 1; rm -f "$t/.fake-ro"; [ "$3" = -r ] && touch "$t/.fake-ro"
    [ "$3" != -r ] && [ -n "$FAKE_BTRFS_FAIL_RW_LEFT" ] && { echo "I/O error" >&2; exit 1; }
    case "$t" in *-before-restore) [ -n "$FAKE_START_DURING" ] && echo running > "$FAKE_START_DURING";; esac
    exit 0;;
  create) [ -e "$3" ] && { echo "ERROR: exists" >&2; exit 1; }; mkdir "$3" && touch "$3/.fake-subvol"; exit $?;;
  delete) [ -f "$3/.fake-subvol" ] || { echo "ERROR: Not a Btrfs subvolume" >&2; exit 1; }; rm -rf "$3"; exit 0;;
esac
exit 1
''')
os.chmod(os.path.join(fakebin, "btrfs"), 0o755)
env = dict(os.environ, PLACES_ROOT=root, DOCKER=fake, PLACE_BIND="10.9.8.7", TZ="UTC", PATH=fakebin + ":" + os.environ.get("PATH", "/usr/bin:/bin"))
fails = []


def check(name, ok, detail=""):
    print(("ok   " if ok else "FAIL ") + name + ("" if ok else f"  {detail}"))
    if not ok:
        fails.append(name)


def run(*args, e=None):
    return subprocess.run([sys.executable, "-I", os.path.join(HERE, "place.py"), *args], capture_output=True, text=True, env=e or env)


r = run("create", "hermic")
calls = open(log).read().splitlines()
check("create makes the container and says it is not started", r.returncode == 0 and "created, not started" in r.stdout and calls[1].startswith("network create") or calls[0].startswith("network inspect"), r.stdout + r.stderr)
c = next(l for l in calls if l.startswith("create --name"))
check("ports bound to the one LAN address only, 3010 -> 3000 and 3011 -> 3001", "-p 10.9.8.7:3010:3000" in c and "-p 10.9.8.7:3011:3001" in c and "0.0.0.0" not in c, c)
check("no-new-privileges, 1 GB shm, restart no, English locale, the volumes", all(x in c for x in ("no-new-privileges", "--shm-size 1gb", "--restart no", "LC_ALL=en_US.UTF-8", "LANG=en_US.UTF-8", "/hermic/desktop:/config", "/hermic/input:/input", "/hermic/output:/output")), c)
check("no GPU runtime unless asked", "nvidia" not in c, c)
check("to-resolve and from-resolve are mounted read-only from the host's copy (a fix needs no image rebuild)", f"{HERE}/bin/to-resolve:/usr/local/bin/to-resolve:ro" in c and f"{HERE}/bin/from-resolve:/usr/local/bin/from-resolve:ro" in c, c)
check("the place lives in its own network, created first with its own /24 and no container-to-container traffic", "--network hermicdoc-net" in c and any(l.startswith("network create") and "--subnet 172.30.1.0/24" in l and "enable_icc=false" in l and l.endswith("hermicdoc-net") for l in calls), (c, calls[:3]))
check("memory, swap, CPUs and process count are limited", all(x in c for x in ("--memory 9g", "--memory-swap 9g", "--cpus 5", "--pids-limit 4096")), c)
envf = os.path.join(root, "hermic", ".desktop.env")
body = open(envf).read()
check("credentials file is 0600 and holds a long password", stat.S_IMODE(os.stat(envf).st_mode) == 0o600 and len(body.split("PASSWORD=")[1].strip()) >= 24, body[:30])
pw = body.split("PASSWORD=")[1].strip()
check("the password is never printed, nor passed on the command line", pw not in r.stdout + r.stderr + c, "")
check("the env file is handed to docker by path", f"--env-file {envf}" in c, c)
r = run("create", "hermic")
check("creating the same place twice is refused and changes nothing", r.returncode == 3 and "already has a place" in r.stderr, r.stderr)
r = run("create", "herlim", e=dict(env, PLACE_MEM="4g", PLACE_CPUS="2.5"))
check("the limits can be tuned and a bad value is refused", "--memory 4g" in open(log).read().splitlines()[-1] and "--cpus 2.5" in open(log).read().splitlines()[-1] and run("create", "herbad", e=dict(env, PLACE_MEM="lots")).returncode == 2, "")
# per place: "mem"/"swap" in .settings.json win over PLACE_MEM; "steam" reaches the container as PLACE_STEAM (default no)
import json as _json
sp = os.path.join(root, "herlim", ".settings.json")
st = _json.load(open(sp)); st.update(mem="12g", swap="4g", steam="auto"); _json.dump(st, open(sp, "w"))
r = run("recreate", "herlim", e=dict(env, PLACE_MEM="4g"))
last = [l for l in open(log).read().splitlines() if l.startswith("create ")][-1]
check("a place's own mem and swap win over PLACE_MEM (RAM 12g, RAM+swap 16384m) and Steam autostart reaches it",
      r.returncode == 0 and "--memory 12g" in last and "--memory-swap 16384m" in last and "PLACE_STEAM=auto" in last, r.stderr + last)
st.pop("mem"); st.pop("swap"); st.pop("steam"); _json.dump(st, open(sp, "w"))
r = run("recreate", "herlim", e=dict(env, PLACE_MEM="4g"))
last = [l for l in open(log).read().splitlines() if l.startswith("create ")][-1]
check("without them: PLACE_MEM, no swap and Steam off, as before", "--memory 4g --memory-swap 4g" in last and "PLACE_STEAM=no" in last, last)
check("a place without the GPU gets no NVIDIA cache settings", "__GL_SHADER_DISK_CACHE" not in last, last)
r = run("steam", "herlim", "maybe")
check("place.py steam refuses anything but auto|no", r.returncode == 2, r.stderr)
r = run("steam", "herlim", "auto")
check("place.py steam saves the choice", r.returncode == 0 and _json.load(open(sp)).get("steam") == "auto", r.stderr)
r = run("mem", "herlim", "12g", "--swap", "4g")
check("place.py mem saves RAM and swap", r.returncode == 0 and _json.load(open(sp)).get("mem") == "12g" and _json.load(open(sp)).get("swap") == "4g", r.stdout + r.stderr)
check("place.py mem refuses a bad size", run("mem", "herlim", "lots").returncode == 2, "")
r = run("create", "herstr", "--gpu")
c2 = open(log).read().splitlines()[-1]
check("the next place takes the next pair of ports, and --gpu adds the NVIDIA runtime", "-p 10.9.8.7:3030:3000" in c2 and "--runtime nvidia" in c2, c2)
check("a GPU place keeps a 16 GB NVIDIA shader cache that is never pruned", "__GL_SHADER_DISK_CACHE_SIZE=17179869184" in c2 and "__GL_SHADER_DISK_CACHE_SKIP_CLEANUP=1" in c2, c2)
for bad in ("Bad", "a", "x" * 25, "../x", "1abc", "a b"):
    check(f"a name like {bad!r} is refused", run("create", bad).returncode == 2)
r = run("create", "other", e=dict(env, PLACE_BIND="8.8.8.8"))
check("a public address is refused for the ports", r.returncode == 2 and "private LAN address" in r.stderr, r.stderr)
r = run("create", "other", e=dict(env, PLACE_BIND="0.0.0.0"))
check("0.0.0.0 is refused too", r.returncode == 2, r.stderr)
r = run("create", "other", e=dict(env, FAKE_FAIL="1"))
check("a docker failure is reported and nothing is called a success", r.returncode == 1 and "could not create" in r.stderr and "created" not in r.stdout, r.stdout + r.stderr)
r = run("creds", "hermic")
check("creds prints the path, not the password", r.stdout.strip() == envf and pw not in r.stdout, r.stdout)
check("start and stop call docker on that container only", run("start", "hermic").returncode == 0 and run("stop", "hermic").returncode == 0 and "start hermicdoc" in open(log).read() and "stop -t 30 hermicdoc" in open(log).read())
check("status prints docker's state", run("status", "hermic").stdout.strip() == "exited")
# --- a Moonlight stream (Sunshine inside the place, its own ports, never /dev/uinput)
r = run("create", "hersun", "--sunshine", "49989")
c3 = open(log).read().splitlines()[-1] if r.returncode == 0 else ""
check("--sunshine publishes the stream ports on the place's own address, TCP and UDP, at the offsets of the base", r.returncode == 0 and all(f"-p 10.9.8.7:{p}:{p}/tcp" in c3 for p in (49984, 49989, 50010)) and all(f"-p 10.9.8.7:{p}:{p}/udp" in c3 for p in (49998, 49999, 50000, 50002)), r.stderr + c3)
check("the admin page's port (base+1) is never published", ":49990" not in c3, c3)
check("the container gets its Sunshine port and name, and no /dev/uinput or other device, no --privileged", "SUNSHINE_PORT=49989" in c3 and "SUNSHINE_NAME=hersun" in c3 and "uinput" not in c3 and "--device" not in c3 and "--privileged" not in c3 and "--cap-add" not in c3, c3)
senv = os.path.join(root, "hersun", ".sunshine.env"); sb = open(senv).read()
check("the admin password is a 0600 file handed over by path, never on the command line or in the output", stat.S_IMODE(os.stat(senv).st_mode) == 0o600 and len(sb.split("=")[1].strip()) >= 24 and f"--env-file {senv}" in c3 and sb.split("=")[1].strip() not in c3 + r.stdout + r.stderr, sb[:25])
check("the base is saved for recreate", json.load(open(os.path.join(root, "hersun", ".settings.json")))["sunshine"] == 49989, "")
r = run("create", "hersun2", "--sunshine", "49990")
check("a base whose ports overlap another place's (the admin page included) is refused", r.returncode == 2 and "overlap" in r.stderr and not os.path.exists(os.path.join(root, "hersun2")), r.stderr)
check("a base out of range is refused", run("create", "hersun3", "--sunshine", "80").returncode == 2, "")
r = run("create", "hernosun")
check("a place without --sunshine publishes none of it", "SUNSHINE" not in open(log).read().splitlines()[-1] and ":49989" not in open(log).read().splitlines()[-1], "")
r = run("recreate", "hersun")
check("recreate keeps the Moonlight settings", r.returncode == 0 and "SUNSHINE_PORT=49989" in open(log).read().splitlines()[-1], r.stderr + r.stdout)
r = run("recreate", "hersun", "--no-sunshine")
check("--no-sunshine takes it off", r.returncode == 0 and "SUNSHINE" not in open(log).read().splitlines()[-1] and json.load(open(os.path.join(root, "hersun", ".settings.json")))["sunshine"] is None, r.stderr)
run("recreate", "hersun", "--sunshine", "49989")
r = run("pair", "hersun", "1234")
pcs = [l for l in open(log).read().splitlines() if l.startswith("exec")][-2:]; pc = " | ".join(pcs)
check("pair asks Sunshine inside the container, from localhost on base+1, as the person's uid, with the PIN as an argument and the password only from the container's env", r.returncode == 0 and re.search(r"-u 30\d\d:30\d\d hersundoc", pc) and "https://127.0.0.1:49990/api/pin" in pc and "$SUNSHINE_ADMIN_PASS" in pc and "sh 1234 hersun 0123456789abcdef0123456789abcdef" in pc and "PIN accepted for phone from 10.0.0.5" in r.stdout and sb.split("=")[1].strip() not in pc + r.stdout, pc)
check("pair refuses a PIN that is not 4 digits and a place with no stream", run("pair", "hersun", "12ab").returncode == 2 and run("pair", "hernosun", "1234").returncode == 3, "")
r = run("rm", "hermic")
check("rm removes the container and leaves the person's folder", "left" in r.stdout and os.path.isdir(os.path.join(root, "hermic", "desktop")), r.stdout)
r = run("create", "hermine", "--ports", "3100", "3101")
check("create --ports takes the two ports it is told (a place that already ran on them)", r.returncode == 0 and "-p 10.9.8.7:3100:3000" in open(log).read().splitlines()[-1] and open(os.path.join(root, "hermine", ".ports")).read().split() == ["3100", "3101"], r.stderr)
r = run("create", "heruno", "--udp", "27960")
cu = open(log).read().splitlines()[-2] if open(log).read().splitlines()[-1].startswith("--") else next(l for l in reversed(open(log).read().splitlines()) if l.startswith("create --name herunodoc"))
check("--udp publishes that UDP port on the place's own LAN address only", "-p 10.9.8.7:27960:27960/udp" in cu and "0.0.0.0" not in cu, cu)
check("the UDP port is saved for recreate", '"udp": [27960]' in open(os.path.join(root, "heruno", ".settings.json")).read(), "")
run("recreate", "heruno")
check("recreate keeps the saved UDP ports", "-p 10.9.8.7:27960:27960/udp" in next(l for l in reversed(open(log).read().splitlines()) if l.startswith("create --name herunodoc")), "")
run("recreate", "heruno", "--no-udp")
check("--no-udp clears them", "/udp" not in next(l for l in reversed(open(log).read().splitlines()) if l.startswith("create --name herunodoc")), "")
for bad in ("80", "70000", "1023"):
    check(f"UDP port {bad} is refused", run("create", "herbadu", "--udp", bad).returncode == 2)
check("more than four UDP ports are refused", run("create", "herfive", *sum([["--udp", str(27000 + i)] for i in range(5)], [])).returncode == 2)
# --- a games place: Steam's runtime and Proton need user namespaces, so it gets its own narrow profiles (never capabilities or --privileged)
r = run("create", "hergame", "--gpu", "--games", e=dict(env, PLACE_GAMES_SECCOMP=os.path.join(tmp, "missing.json")))
check("--games on a host without the profiles is refused before anything is written", r.returncode == 3 and "install-games-profile.sh" in r.stderr and not os.path.exists(os.path.join(root, "hergame", ".desktop.env")), r.stderr)
sec = os.path.join(tmp, "seccomp-games.json"); open(sec, "w").write("{}"); cdi = os.path.join(tmp, "bridgeai-games.json"); open(cdi, "w").write("{}")
genv = dict(env, PLACE_GAMES_SECCOMP=sec, PLACE_GAMES_CDI=cdi)
r = run("create", "hergame", "--gpu", "--games", e=genv)
cg = next(l for l in reversed(open(log).read().splitlines()) if l.startswith("create --name hergamedoc"))
check("--games adds the seccomp and AppArmor profiles and an unmasked /proc, and keeps no-new-privileges", r.returncode == 0 and all(x in cg for x in (f"seccomp={sec}", "apparmor=bridgeai-place-games", "systempaths=unconfined", "no-new-privileges")), r.stderr + cg)
check("a games place never gets capabilities, --privileged or /dev/uinput", not any(x in cg for x in ("--cap-add", "--privileged", "uinput")), cg)
check("its GPU is the games CDI device (32-bit libraries, no /proc override), not the NVIDIA runtime", "--device bridgeai.local/games=all" in cg and "--runtime nvidia" not in cg, cg)
check("--games defaults to the Steam image and is saved for recreate", cg.endswith("bridgeai-place-steam:latest") and json.load(open(os.path.join(root, "hergame", ".settings.json")))["games"] is True, cg)
run("recreate", "hergame", e=genv)
cg = next(l for l in reversed(open(log).read().splitlines()) if l.startswith("create --name hergamedoc"))
check("recreate keeps the games profile", "apparmor=bridgeai-place-games" in cg and "--device bridgeai.local/games=all" in cg, cg)
run("recreate", "hergame", "--no-games", e=genv)
cg = next(l for l in reversed(open(log).read().splitlines()) if l.startswith("create --name hergamedoc"))
check("--no-games takes the profiles off and goes back to the NVIDIA runtime", "seccomp=" not in cg and "systempaths" not in cg and "--runtime nvidia" in cg, cg)
check("a place without --games has none of it", "seccomp=" not in c and "systempaths" not in c and "apparmor=" not in c, c)
import importlib.util
spec = importlib.util.spec_from_file_location("msu", os.path.join(HERE, "make-seccomp-userns.py")); msu = importlib.util.module_from_spec(spec); spec.loader.exec_module(msu)
dflt = {"defaultAction": "SCMP_ACT_ERRNO", "syscalls": [{"names": ["read", "write"], "action": "SCMP_ACT_ALLOW"},
        {"names": ["bpf", "mount", "unshare", "setns", "perf_event_open"], "action": "SCMP_ACT_ALLOW", "includes": {"caps": ["CAP_SYS_ADMIN"]}},
        {"names": ["clone"], "action": "SCMP_ACT_ALLOW", "args": [{"index": 0, "value": 2114060288, "op": "SCMP_CMP_MASKED_EQ"}]},
        {"names": ["kexec_load"], "action": "SCMP_ACT_ALLOW", "includes": {"caps": ["CAP_SYS_BOOT"]}}]}
out = msu.build(dflt)
allowed = {n for r in out["syscalls"] if r["action"] == "SCMP_ACT_ALLOW" and not r.get("includes") and not r.get("args") for n in r["names"]}
check("the games seccomp profile opens only the user-namespace calls; bpf, perf_event_open and kexec stay behind their capabilities", {"mount", "unshare", "setns", "clone", "pivot_root"} <= allowed and not {"bpf", "perf_event_open", "kexec_load"} & allowed and out["defaultAction"] == "SCMP_ACT_ERRNO", sorted(allowed))
check("the source profile is not changed", dflt["syscalls"][1]["names"] == ["bpf", "mount", "unshare", "setns", "perf_event_open"], "")
